'use strict';
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { promisify } = require('node:util');
const exec = promisify(require('node:child_process').execFile);

function physicsGuardBuilder() {
  // Keep generated bytecode consistent with the Java sources captured by this verifier.
  const sources = Object.fromEntries(['PreparePhysicsGuard', 'PhysicsGuardAgent'].map(name =>
    [name, fs.readFileSync(path.join(__dirname, 'native-speed', `${name}.java`), 'utf8')]));
  return async function prepare(paperDir, serverJar, dependencies, { signal } = {}) {
    const root = path.join(paperDir, 'mcbench-speed');
    const hash = crypto.createHash('sha256').update(JSON.stringify(sources)).update(fs.readFileSync(serverJar)).digest('hex');
    const stamp = path.join(root, 'build.sha256');
    const output = path.join(root, 'physics-guard.jar');
    if (fs.existsSync(output) && fs.existsSync(stamp) && fs.readFileSync(stamp, 'utf8') === hash) return true;
    fs.mkdirSync(root, { recursive: true });
    // No stamp while the jar changes: a build cut short is built again.
    fs.rmSync(stamp, { force: true });
    for (const [name, source] of Object.entries(sources)) fs.writeFileSync(path.join(root, `${name}.java`), source);
    const cp = dependencies.join(path.delimiter);
    await exec(process.env.MCBENCH_JAVAC || 'javac', ['--release', '21', '-proc:none', '-cp', cp, '-d', root, ...Object.keys(sources).map(name => path.join(root, `${name}.java`))], { signal, timeout: 60_000 });
    try {
      await exec(process.env.MCBENCH_JAVA || 'java', ['-cp', root + path.delimiter + cp, 'PreparePhysicsGuard', serverJar, root], { signal, timeout: 30_000 });
    } catch (error) {
      if (error.code !== 42) throw error;
      return false; // Unsupported server bytecode must retain stock behavior.
    }
    fs.writeFileSync(path.join(root, 'manifest.mf'), 'Manifest-Version: 1.0\nPremain-Class: PhysicsGuardAgent\n\n');
    await exec(process.env.MCBENCH_JAR || 'jar', ['cfm', `${output}.part`, path.join(root, 'manifest.mf'), '-C', root, 'PhysicsGuardAgent.class', '-C', root, 'PhysicsGuardAgent$1.class'], { signal, timeout: 30_000 });
    fs.renameSync(`${output}.part`, output);
    fs.writeFileSync(stamp, hash);
    return true;
  };
}
module.exports = { physicsGuardBuilder };
